// n을 소인수분해해 (소수, 지수)를 출력한다
for (int p = 2; p * p <= n; p++) {
    int e = 0;
    while (n % p == 0) { n /= p; e++; }
    if (e > 0) print(p, e);
}
if (n > 1) print(n, 1);                 // 남은 수는 소수

